// Isolated production attribution only; not part of the candidate source.
function IsolatedProductionGlAttribution() {
  const gl = useThree(state => state.gl);
  useEffect(() => {
    if (new URLSearchParams(window.location.search).get("qaGlDiagnostic") !== "1") return;
    const context = gl.getContext();
    const debugRenderer = context.getExtension("WEBGL_debug_renderer_info");
    console.info("[Pool3D production renderer]", JSON.stringify({
      renderer: debugRenderer ? context.getParameter(debugRenderer.UNMASKED_RENDERER_WEBGL) : context.getParameter(context.RENDERER),
      vendor: debugRenderer ? context.getParameter(debugRenderer.UNMASKED_VENDOR_WEBGL) : context.getParameter(context.VENDOR),
      version: context.getParameter(context.VERSION),
      shadingLanguageVersion: context.getParameter(context.SHADING_LANGUAGE_VERSION),
      KHR_parallel_shader_compile: gl.extensions.has("KHR_parallel_shader_compile"),
      dpr: gl.getPixelRatio(), cssWidth: gl.domElement.clientWidth, cssHeight: gl.domElement.clientHeight,
      geometries: gl.info.memory.geometries, textures: gl.info.memory.textures, programs: gl.info.programs?.length,
    }));
    return installDevelopmentGlDiagnostic(context);
  }, [gl]);
  return null;
}
